export default function next({ rows, previous }) {
  const i = previous?.next ?? 0;
  if (!Array.isArray(rows) || !Number.isInteger(i) || i < 0 || i > rows.length)
    throw Error("Invalid row state");
  return {
    state: { next: i + 1 },
    more: i < rows.length,
    records: i < rows.length ? [{ fields: rows[i] }] : [{ fields: {} }],
  };
}

